const raw = $json.stdout ?? '';
let result;
try {
  result = JSON.parse(raw);
} catch {
  throw new Error('The render did not return JSON. stderr: ' + ($json.stderr ?? '').slice(-800));
}
if (!result.ok) {
  throw new Error(result.error);
}
return [{ json: result }];

